INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (10.85, "エリコ", 24, 100, 7, "2030/12/17 14:59:59", 129901, 1, 100, "2024/03/31 12:00:00", 0, 0, 10142, "訓練成功、おめでとうございます\n褒めるべき時にはしっかり褒めるのも\n教官の務めですものね。それとも、\n罵られる方が好みですか？　クスクス");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (11.15, "エリコ", 24, 101, 2, "2030/12/17 14:59:59", 129901, 1, 101, "2024/03/31 12:00:00", 0, 0, 10142, "厳しい訓練も、終わってみれば\n短く感じるものですわね。\n正直、私は暴れ足りないくらい…\nいえ、何でもありませんわ。クスクス");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (6.4, "エリコ", 24, 102, 5, "2030/12/17 14:59:59", 129901, 7, 102, "2024/03/31 12:00:00", 0, 0, 10142, "行く手を阻む忌々しい邪魔者を\n蹴散らして、見事ゴールイン…！\nまるで私とあのおかたの人生を\n象徴するような道のりでした…");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (0, "エリコ", 24, 103, 3, "2030/12/17 14:59:59", 129901, 3, 103, "2024/03/31 12:00:00", 0, 0, 10142, "まったくもって不甲斐ない結果です\nしかし、挽回の機会はまだありますわ\n次はゴミ虫の地位から脱却できるよう\n死力を尽くしなさい。いいですね？");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (2.43, "エリコ", 24, 104, 8, "2030/12/17 14:59:59", 129901, 2, 104, "2024/03/31 12:00:00", 0, 0, 10142, "クスクス…ああご心配なさらず\nなんとも情けない成績を残す輩には\nどんな罰が相応しいか、考えている\nだけですので…クスクスクス");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (9.08, "エリコ", 24, 105, 3, "2030/12/17 14:59:59", 129901, 4, 105, "2024/03/31 12:00:00", 0, 0, 10142, "私が教官として認められなければ、\nあのおかたを失望させてしまう…\nそれだけはあってはなりません\nあなた方も、わかっていますわね？");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (0, "エリコ", 24, 106, 6, "2030/12/17 14:59:59", 129901, 6, 106, "2024/03/31 12:00:00", 0, 0, 10142, "まずまずの結果ではありますが、\nこの程度で満足してもらっては\n困りますわ。エリコ班の一員として、\nより高みを目指していただきますので");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (10.6, "エリコ", 24, 107, 8, "2030/12/17 14:59:59", 129901, 3, 107, "2024/03/31 12:00:00", 0, 0, 10142, "私の指導を受けながら、この結果は…\nもっと真剣に考えねばなりませんね\nあなた方が怠けずにいるには、\nどんなしつけが必要かを…クスクス");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (7.54, "エリコ", 24, 108, 4, "2030/12/17 14:59:59", 129901, 6, 108, "2024/03/31 12:00:00", 0, 0, 10142, "ひとまず訓練をこなしたご褒美か、\n実力を出しきれたとは言えない罰か…\nみなさんにどちらを与えるべきか\n少し悩む結果ですわね");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (11.5, "エリコ", 24, 109, 7, "2030/12/17 14:59:59", 129901, 2, 109, "2024/03/31 12:00:00", 0, 0, 10142, "なかなかいい戦いぶりでしたわ\nこれもあなた方の頑張りと、何より\n優秀な教官である私の教育の賜物\nそうですわね？　クスクスクス…");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (8.83, "エリコ", 24, 110, 1, "2030/12/17 14:59:59", 129901, 2, 110, "2024/03/31 12:00:00", 0, 0, 10142, "これだけ進めたのならば合格点ですわ\nでも、もっと高みを目指したいと\n思っているのなら…さらなる訓練にも\n付き合って差し上げましょう");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (6.68, "エリコ", 24, 111, 2, "2030/12/17 14:59:59", 129901, 1, 111, "2024/03/31 12:00:00", 0, 0, 10142, "未熟で頼りなかったあなた方が、\n見違えるように成長しました\nなるほど…これこそが、教官冥利に\n尽きるという気持ちなのですね");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (8.8, "エリコ", 24, 112, 2, "2030/12/17 14:59:59", 129901, 6, 112, "2024/03/31 12:00:00", 0, 0, 10142, "まさかあなた方が、私の予想すら\n超える力を発揮するとは…驚きました\nもはやゴミ虫などではありません\n一人前の騎士として胸を張りなさい");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (8.9, "エリコ", 24, 113, 1, "2030/12/17 14:59:59", 129901, 2, 113, "2024/03/31 12:00:00", 0, 0, 10142, "クスクス、見事な働きです\nみなさんならできると信じていました\n他でもない私の指導を受けた、\nエリコ班の優秀な新兵なのですから");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (3.7, "エリコ", 24, 114, 5, "2030/12/17 14:59:59", 129901, 2, 114, "2024/03/31 12:00:00", 0, 0, 10142, "なんてすばらしい成績…！\n今日という日は『あのおかたを想い\nエリコが限界を超えた記念日』として\n歴史に刻まれることでしょう…！");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (7.6, "マコト", 24, 200, 2, "2030/12/17 14:59:59", 129801, 1, 200, "2024/03/31 12:00:00", 0, 0, 10142, "よし、いい訓練になったな\nおまえたちもよく動けてたし、\nちゃんと成長できてると思うぜ\nその調子で頑張れよっ");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (2.25, "マコト", 24, 201, 1, "2030/12/17 14:59:59", 129801, 2, 201, "2024/03/31 12:00:00", 0, 0, 10142, "ひとまずゴールおめでとう！\nでも、努力は継続してこそだからな\nおまえたちにやる気があるなら、\n何度だって付き合ってやるよ");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (3.28, "マコト", 24, 202, 1, "2030/12/17 14:59:59", 129801, 2, 202, "2024/03/31 12:00:00", 0, 0, 10142, "行軍訓練はこれにて完了！\n…なーんて思ってないよな？\n学んだことが体に染みつくまで\n地道に繰り返すのが練習ってもんさ");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (2.98, "マコト", 24, 203, 1, "2030/12/17 14:59:59", 129801, 4, 203, "2024/03/31 12:00:00", 0, 0, 10142, "みんなに無理をさせちまったか…\nでもこれで諦めることはないぜ\n次はきっとうまくいく。そう信じて\n鍛え続ければ、道は開けるはずだ！");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (3, "マコト", 24, 204, 1, "2030/12/17 14:59:59", 129801, 4, 204, "2024/03/31 12:00:00", 0, 0, 10142, "こいつは悔しい結果だな…\nま、反省点はいろいろあったし\nひとつずつ乗り越えていこう\nあたしたちで力を合わせて、なっ！");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (10.3, "マコト", 24, 205, 2, "2030/12/17 14:59:59", 129801, 1, 205, "2024/03/31 12:00:00", 0, 0, 10142, "おまえたちはまだ未熟な訓練兵、\n失敗を必要以上に悔やむことはねえよ\nでも実戦じゃこうはいかないからな\n次は気合を入れ直していけよっ！");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (2.93, "マコト", 24, 206, 1, "2030/12/17 14:59:59", 129801, 6, 206, "2024/03/31 12:00:00", 0, 0, 10142, "これがおまえたちの全力？\nいやいや、そんなはずはないよなっ\nおまえらならもっと強くなれる！\nあたしが言うんだ、間違いないぜ！");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (9.3, "マコト", 24, 207, 1, "2030/12/17 14:59:59", 129801, 3, 207, "2024/03/31 12:00:00", 0, 0, 10142, "おまえたちの実力を考えりゃ、\nベストを尽くせたとは言えない成績だ\nなら、次やるべきことも決まってる\n気持ちを切り替えて、鍛え直すんだ！");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (6.9, "マコト", 24, 208, 1, "2030/12/17 14:59:59", 129801, 4, 208, "2024/03/31 12:00:00", 0, 0, 10142, "まだまだ課題がある内容だったな～\n無駄な動き、判断の遅れ…\nそういうのをしっかり直していけば、\n記録ももっと伸びるはずだっ");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (0, "マコト", 24, 209, 2, "2030/12/17 14:59:59", 129801, 2, 209, "2024/03/31 12:00:00", 0, 0, 10142, "ここまでいけりゃ、合格点！\nむしろ、最初の頼りなさを思えば\nすげえ成長してるんじゃねえか？\n胸を張れる結果だと思うぜっ！");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (5.95, "マコト", 24, 210, 2, "2030/12/17 14:59:59", 129801, 1, 210, "2024/03/31 12:00:00", 0, 0, 10142, "なかなかハードな訓練だったけど、\nみんなしっかりついてこられたな\n地道に続けた基礎トレの成果が\n形になってる、その証だぜっ");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (6.73, "マコト", 24, 211, 1, "2030/12/17 14:59:59", 129801, 2, 211, "2024/03/31 12:00:00", 0, 0, 10142, "今回の訓練もよく頑張ったな！\nしっかり休んで次に備えろよ！\nなんつーか、教え子が成長してくのを\n見るのは楽しいもんだな…");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (0, "マコト", 24, 212, 2, "2030/12/17 14:59:59", 129801, 2, 212, "2024/03/31 12:00:00", 0, 0, 10142, "おまえら、すげえじゃねえか！\nこれならもう、ひよっこ新兵なんて\n言えねえな。きっと騎士団でも\n大活躍間違いなしだぜ！");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (6.65, "マコト", 24, 213, 2, "2030/12/17 14:59:59", 129801, 1, 213, "2024/03/31 12:00:00", 0, 0, 10142, "敵との戦い方、状況判断の正確さ\n何より根性…どれも最高だったぞ！\nうかうかしてたら、教官のあたしまで\n追い抜かれちまうかもな…へへっ");
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (3.05, "マコト", 24, 214, 1, "2030/12/17 14:59:59", 129801, 6, 214, "2024/03/31 12:00:00", 0, 0, 10142, "あたしの指導が良かった？\nいやいや、ここまで強くなれたのは、\n他でもないおまえたち自身が努力した\nおかげだよ。改めて…おめでとうっ！");
